def region(title,body,section='content',kind='content-band'):
 return f'<section data-section="{section}" data-component="{kind}"><h2>{title}</h2>{body}</section>'
def card(title,text,link,label='Explore'):
 return f'<article data-section="product-options" data-component="content-card"><h3>{title}</h3><p>{text}</p><a href="{link}">{label} <span aria-hidden="true">→</span></a></article>'
def faq(q,a):return f'<details data-section="questions" data-component="accordion"><summary>{q}</summary><p>{a}</p></details>'
